const allowedOrigins = ['https://dashboard.example.com', 'https://admin.example.com'];

export function GET(request) {
  const headers = new Headers({ 'Content-Type': 'application/json', Vary: 'Origin' });
  const origin = request.headers.get('origin');
  if (allowedOrigins.includes(origin)) {
    headers.set('Access-Control-Allow-Origin', origin);
    headers.set('Access-Control-Allow-Credentials', 'true');
  }
  return new Response(JSON.stringify({ account: 'demo', plan: 'free' }), { headers });
}

