from pathlib import Path

def download(root, request):
    base = Path(root).resolve()
    supplied = Path(request.args['path'])
    if supplied.is_absolute():
        raise ValueError('Absolute document path')
    candidate = (base / supplied).resolve()
    if not candidate.is_relative_to(base):
        raise ValueError('Document is outside root')
    with candidate.open(encoding='utf-8') as document:
        return document.read()

